import random

class Skiplist:
    MAX_LEVEL = 16
    P = 0.5

    class Node:
        __slots__ = ("val", "next")
        def __init__(self, val, level):
            self.val = val
            self.next = [None] * level

    def __init__(self):
        self.head = self.Node(-1, self.MAX_LEVEL)

    def _find(self, num):
        update = [self.head] * self.MAX_LEVEL
        cur = self.head
        for i in range(self.MAX_LEVEL - 1, -1, -1):
            while cur.next[i] and cur.next[i].val < num:
                cur = cur.next[i]
            update[i] = cur
        return update

    def search(self, target: int) -> bool:
        cur = self.head
        for i in range(self.MAX_LEVEL - 1, -1, -1):
            while cur.next[i] and cur.next[i].val < target:
                cur = cur.next[i]
        cur = cur.next[0]
        return cur is not None and cur.val == target

    def add(self, num: int) -> None:
        update = self._find(num)
        level = 1
        while level < self.MAX_LEVEL and random.random() < self.P:
            level += 1
        node = self.Node(num, level)
        for i in range(level):
            node.next[i] = update[i].next[i]
            update[i].next[i] = node

    def erase(self, num: int) -> bool:
        update = self._find(num)
        node = update[0].next[0]
        if not node or node.val != num:
            return False
        for i in range(len(node.next)):
            if update[i].next[i] == node:
                update[i].next[i] = node.next[i]
        return True

