class Skiplist:
    def __init__(self):
        self.head = [-1, None]
        self.size = 0
        self.index = [self.head]

    def _rebuild(self):
        step = max(1, self.size // 32)
        self.index = []
        cur = self.head
        cnt = 0
        while cur:
            if cnt % step == 0:
                self.index.append(cur)
            cur = cur[1]
            cnt += 1

    def _locate(self, num):
        start = self.head
        for node in self.index:
            if node[0] < num:
                start = node
            else:
                break
        prev = start
        while prev[1] and prev[1][0] < num:
            prev = prev[1]
        return prev

    def search(self, target: int) -> bool:
        prev = self._locate(target)
        return prev[1] is not None and prev[1][0] == target

    def add(self, num: int) -> None:
        prev = self._locate(num)
        prev[1] = [num, prev[1]]
        self.size += 1
        if self.size & (self.size - 1) == 0:
            self._rebuild()

    def erase(self, num: int) -> bool:
        prev = self._locate(num)
        if prev[1] and prev[1][0] == num:
            prev[1] = prev[1][1]
            self.size -= 1
            return True
        return False

