    Node* head;
    int size = 0;
    vector<Node*> index;
    void rebuild() {
        int step = max(1, size / 32);
        index.clear();
        Node* cur = head;
        for (int c = 0; cur; cur = cur->nxt, c++)
            if (c % step == 0) index.push_back(cur);
    }
    Node* locate(int num) {
        Node* prev = head;
        for (Node* n : index)
            if (n->val < num) prev = n; else break;
        while (prev->nxt && prev->nxt->val < num) prev = prev->nxt;
        return prev;
    }
public:
    Skiplist() { head = new Node{-1, nullptr}; index.push_back(head); }
    bool search(int t) {
        Node* p = locate(t);
        return p->nxt && p->nxt->val == t;
    }
    void add(int num) {
        Node* p = locate(num);
        p->nxt = new Node{num, p->nxt};
        if (++size && (size & (size - 1)) == 0) rebuild();
    }
    bool erase(int num) {
        Node* p = locate(num);
        if (p->nxt && p->nxt->val == num) {
            Node* d = p->nxt; p->nxt = d->nxt; delete d;
            size--; return true;
        }
        return false;
    }
};

