class Skiplist {
    private static class Node { int val; Node nxt; Node(int v){val=v;} }
    private final Node head = new Node(-1);
    private int size = 0;
    private java.util.ArrayList<Node> index = new java.util.ArrayList<>();

    private void rebuild() {
        int step = Math.max(1, size / 32);
        index.clear();
        Node cur = head;
        for (int c = 0; cur != null; cur = cur.nxt, c++)
            if (c % step == 0) index.add(cur);
    }
    private Node locate(int num) {
        Node prev = head;
        for (Node n : index) { if (n.val < num) prev = n; else break; }
        while (prev.nxt != null && prev.nxt.val < num) prev = prev.nxt;
        return prev;
    }
    public Skiplist() { index.add(head); }
    public boolean search(int t) {
        Node p = locate(t);
        return p.nxt != null && p.nxt.val == t;
    }
    public void add(int num) {
        Node p = locate(num);
        Node n = new Node(num); n.nxt = p.nxt; p.nxt = n;
        size++;
        if ((size & (size - 1)) == 0) rebuild();
    }
    public boolean erase(int num) {
        Node p = locate(num);
        if (p.nxt != null && p.nxt.val == num) {
            p.nxt = p.nxt.nxt; size--; return true;
        }
        return false;
    }
}

